if($('race-coverage'))$('race-coverage').onchange=e=>{state.statewideView=e.target.value;state.selected=null;state.zoom=1;state.panX=state.panY=0;state.pageIndex=0;state.countySearch='';renderRace()};$('map-geography').value=countyComparisonView()?'counties':state.mapGeography;$('map-geography').onchange=e=>{state.mapGeography=e.target.value;state.zoom=1;state.panX=state.panY=0;drawMap()};$('map-layer').value=state.layer;$('map-layer').onchange=e=>{state.layer=e.target.value;state.zoom=1;state.panX=state.panY=0;drawMap()};
