function countyTableHTML(r){const rows=(r.county_results||[]).filter(c=>c.county.toLowerCase().includes(state.countySearch.toLowerCase()));const label=state.targetParty==='dem'?'D':'R';return `<section class="section" id="county-section"><div class="section-head"><h2>County returns</h2><button id="export-counties" class="button">Export county totals (CSV)</button></div><p class="note">One source per race and county is counted. County totals never create precinct rows. Turnout vs 2024 is reported contest votes divided by all 2024 presidential votes, shown only at 100% source reporting. It measures vote volume, not registered-voter turnout or ballots cast. ≥ marks omitted write-ins; ≈ marks an estimated historical reference. County-only fallbacks are attributed to <a href="https://civicapi.org/" target="_blank" rel="noreferrer">civicAPI</a>; its reporting percentage is estimated and it omits write-ins. ${statewideCountyView()?'Historical shares use 2024 presidential results for each whole county.':'Historical shares below are modeled 2024 presidential results for the same county portion of this view.'}</p><label for="county-search">Find a county</label><input id="county-search" type="search" placeholder="County name" value="${esc(state.countySearch)}">${rows.length?`<div class="table-wrap"><table id="county-table"><thead><tr><th>County</th><th>Published candidates</th><th>Votes</th><th>Reporting level</th><th>Turnout vs 2024</th><th>2024 ${label} share</th><th>${label} target</th><th>Target gap</th><th>Est. reporting</th><th>Source</th></tr></thead><tbody>${rows.map(c=>`<tr><td data-label="County">${esc(c.county)}</td><td data-label="Candidates">${(c.candidates||[]).map(x=>`<div class="${party(x.party)}">${esc(x.name)}: <strong class="num">${fmt(x.votes)}</strong></div>`).join('')}${c.write_ins_supplied===false&&c.write_ins_applicable!==false?'<small>Write-ins not supplied</small>':''}</td><td data-label="Votes" class="num">${fmt(c.total)}</td><td data-label="Reporting level">${c.precinct_detail?'Precinct detail':'County totals only'}</td>${turnoutHTML(benchmarkForCounty(c),c)}${benchmarkCells(benchmarkForCounty(c),c)}<td data-label="Est. reporting">${pct(c.estimated_reporting)}</td><td data-label="Source"><a href="${esc(c.url)}" target="_blank" rel="noreferrer">${esc(c.publisher)}</a><small>Published ${esc(time(c.published_at))}</small><small>Retrieved ${esc(time(c.fetched_at))}</small></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No accepted county contributions yet.</p>'}</section>`}
function benchmarkTableHTML(){const records=benchmarkRecords(),label=state.targetParty==='dem'?'D':'R';return `<section class="section" id="benchmark-section"><details id="benchmark-disclosure" ${state.benchmarkOpen?'open':''}><summary>All 2024 presidential area benchmarks</summary><p class="note">${statewideCountyView()?'2024 presidential results aggregated by whole county. These references retain their source provenance; county maps require no seat-split allocation.':'≈ Estimated 2024 votes on current areas. Census 2020 adult-population points allocate historical precinct votes to each seat’s precinct or county portion. No land-area vote allocation or live-vote allocation is used. A dash means no usable adult weight, not zero voters.'}</p><button id="export-benchmarks" class="button">Export 2024 benchmarks (CSV)</button><div class="table-wrap"><table id="benchmark-table"><thead><tr><th>Area</th><th>Level</th><th>2024 ${label} share</th><th>${label} target</th><th>≈ 2024 two-party votes</th></tr></thead><tbody>${records.map(u=>`<tr><td data-label="Area">${esc(u.name)}</td><td data-label="Level">${u.kind==='county'?(statewideCountyView()?'County':'County portion'):'Precinct portion'}</td><td data-label="2024 reference">${pct(referenceShare(u))}</td><td data-label="Target share">${pct(selectedTarget(u))}</td><td data-label="2024 votes">${u.available?'≈ '+fmt(Math.round(u.two_party_votes)):'—'}</td></tr>`).join('')}</tbody></table></div></details></section>`}
function renderBenchmarkTables(){const open=$('benchmark-disclosure')?.open;$('county-section').outerHTML=countyTableHTML(race());$('benchmark-section').outerHTML=benchmarkTableHTML();if(open)$('benchmark-disclosure').open=true;$('export-counties').onclick=exportCounties;$('export-benchmarks').onclick=exportBenchmarks;$('benchmark-disclosure').ontoggle=e=>{state.benchmarkOpen=e.currentTarget.open};bindCountySearch();renderSelection()}
function al02ResearchHTML(){const checks=state.data.al02_research?.counties||[];return `<section class="section"><h2>AL-02 precinct feed coverage</h2><p class="note">Each county’s official results pages were checked for November 3 general-election precinct returns. County-level civicAPI totals update automatically; a historical report, precinct map or sample ballot does not establish a current precinct feed. Checked ${esc(time(state.data.al02_research?.checked_at))}.</p><div class="coverage-list">${checks.map(c=>`<div class="county"><strong>${esc(c.county)}</strong><small>${c.eligible_precinct_feed?'Verified current precinct feed':'No eligible current precinct feed verified'}</small><details><summary>Source check</summary><p>${esc(Array.isArray(c.notes)?c.notes.join(' '):c.notes||c.status)}</p>${c.official_url?`<a href="${esc(c.official_url)}" target="_blank" rel="noreferrer">Official county source</a>`:''}</details></div>`).join('')}</div></section>`;}
function coverageCards(r){const candidates=(statewideCountyView()?state.statewideGeo:r.scope==='cd2'?state.al02Geo:state.geo).features.filter(f=>f.properties.kind==='county');const counties=r.scope==='cd5'||r.scope==='cd2'||statewideCountyView()?candidates:candidates.filter(f=>f.properties.name==='Madison'||(r.county_results||[]).some(c=>c.county===f.properties.name));return counties.map(f=>{const name=f.properties.name;const c=(r.county_results||[]).find(c=>c.county===name);const official=state.data.sources.find(s=>s.source.county===name);return `<div class="county"><strong>${esc(name)}</strong><small>${name==='Lauderdale'&&r.scope==='cd5'?'Eastern county within CD-5':r.scope==='cd5'?'CD-5 contest returns':r.scope==='cd2'?'AL-02 district-specific returns':'Contest-specific county returns'}</small><span>${c?fmt(c.total)+' votes; '+(c.precinct_detail?'precinct detail available':'county totals only'):esc(official?sourceStatus(official):'No accepted feed')}</span>${c?`<small>${esc(c.publisher)}</small>`:''}</div>`}).join('')}
function currentUnits(){return(race().units||[]).filter(u=>(state.county==='all'||u.county===state.county)&&u.name.toLowerCase().includes(state.unitSearch.toLowerCase())).sort((a,b)=>{if(state.sort==='votes')return b.total-a.total;if(state.sort==='dem'||state.sort==='rep'){const f=u=>{const p=twoParty(u);return p.total?(state.sort==='dem'?p.d:p.r)/p.total:-1};return f(b)-f(a)}return a.county.localeCompare(b.county)||a.name.localeCompare(b.name)})}
function renderTable(){const all=currentUnits(),pageSize=20;state.pageIndex=Math.max(0,Math.min(state.pageIndex,Math.ceil(all.length/pageSize)-1));const rows=all.slice(state.pageIndex*pageSize,(state.pageIndex+1)*pageSize),r=race(),label=state.targetParty==='dem'?'D':'R';$('unit-table').innerHTML=all.length?`<table><thead><tr><th>Reporting unit</th><th>County</th><th>Votes</th><th>D share</th><th>R share</th><th>Turnout vs 2024</th><th>2024 ${label} share</th><th>${label} target</th><th>Target gap</th><th>Status</th></tr></thead><tbody>${rows.map(u=>{const p=twoParty(u),base=historicalFor(u);return `<tr class="${u.id===state.selected?'selected':''}"><td data-label="Reporting unit"><button class="unit-button" data-unit="${esc(u.id)}">${esc(u.name)}</button></td><td data-label="County">${esc(u.county)}</td><td data-label="Votes" class="num">${fmt(u.total)}</td><td data-label="D share" class="num ${p.total?'dem':''}">${pct(p.total?100*p.d/p.total:null)}</td><td data-label="R share" class="num ${p.total?'rep':''}">${pct(p.total?100*p.r/p.total:null)}</td>${turnoutHTML(base,u)}${benchmarkCells(base,u)}<td data-label="Status">${u.administrative?'Administrative':u.reporting_complete===true?'100% reporting':u.total>0?'Votes received':'No votes published'}<small>${base?'Modeled 2024 reference':u.administrative?'Excluded from geographic benchmark':'2024 reference unavailable'}</small></td></tr>`}).join('')}</tbody></table>`:`<div class="empty"><h3>${r.units.length?'No reporting units match':'Precinct results are pending'}</h3><p>${r.units.length?'Change the search or county filter.':r.contributions.length?'County totals are available above. No accepted precinct breakdown is supplied for this race.':'No verified current-election feed has been accepted for this race.'}</p></div>`;$('pager').innerHTML=all.length?`<span>${state.pageIndex*pageSize+1}–${Math.min((state.pageIndex+1)*pageSize,all.length)} of ${all.length} reporting units</span><div><button id="prev-page" ${state.pageIndex===0?'disabled':''}>Previous</button><button id="next-page" ${(state.pageIndex+1)*pageSize>=all.length?'disabled':''}>Next</button></div>`:'';$('unit-table').querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.unit;renderSelection();renderTable();highlightSelection()});if($('prev-page')){$('prev-page').onclick=()=>{state.pageIndex--;renderTable()};$('next-page').onclick=()=>{state.pageIndex++;renderTable()}}}
function updateTarget(){const records=benchmarkRecords(),cal=calibration(),r=race();const obs=[];for(const u of r.units||[]){const base=historicalFor(u);if(base){const p=twoParty(u);obs.push({d:p.d,r:p.r,targetDem:targetFor(base)})}}for(const c of r.county_results||[]){if(countyComparisonView()||!c.precinct_detail){const base=benchmarkForCounty(c),p=twoParty(c);if(base)obs.push({d:p.d,r:p.r,targetDem:targetFor(base)})}}const result=ElectionBenchmarks.compare(comparableRace()?obs:[],state.targetParty);const share=state.targetParty==='dem'?cal.referenceDemShare:cal.referenceDemShare==null?null:100-cal.referenceDemShare;$('target-result').innerHTML=`<p>2024 ${state.targetParty==='dem'?'D':'R'} reference: <strong>${pct(share)}</strong><br>${records.filter(ElectionBenchmarks.usable).length} of ${records.length} areas have ${statewideCountyView()?'county':'modeled'} benchmarks.</p>${result.total?`<strong class="${state.targetParty}">${signed(result.gap)}</strong> against target in ${result.count} reported areas.<br><span class="note">Current share ${pct(result.actualShare)}; target for those same reported votes ${pct(result.targetShare)}. Provisional comparison; no projected finish.</span>`:`<p>${comparableRace()?'No positive comparable returns yet. Benchmarks and targets are available before counting begins.':'The 2024 reference is available. A D/R target gap is not defined for this ballot’s candidate field.'}</p>`}<p class="note">Targets are calibrated to ${state.target}% ${state.targetParty==='dem'?'Democratic':'Republican'} in ${benchmarkScope()==='madison'?'Madison County’s':statewideCountyView()?'Alabama’s':'the selected seat’s'} available historical reference. ${countyComparisonView()?'County-level comparisons include their published administrative ballots.':'Historical splits are estimates. Administrative ballots are excluded from precinct comparisons.'}</p>`}
function coordinates(g){return g.type==='Polygon'?g.coordinates.flat():g.coordinates.flat(2)}
let mapFeatures=[];
function drawMap(){const r=race(),scope=benchmarkScope(),seat=seatReference(scope);let district=null;
if(scope==='alabama')mapFeatures=state.statewideGeo.features;
else if(seat){mapFeatures=state.mapGeography==='counties'||scope==='cd2'?seat.county_features:state.seatGeo.features.filter(f=>f.properties.seat_id===scope&&!f.properties.boundary_resolution_sliver);district={geometry:seat.geometry};}
else if(state.mapGeography==='counties')mapFeatures=state.geo.features.filter(f=>f.properties.kind==='county'&&f.properties.county_id==='01089');
else mapFeatures=state.currentGeo.features;
const coords=(district?coordinates(district.geometry):mapFeatures.flatMap(f=>coordinates(f.geometry)));if(!coords.length){$('map-shapes').innerHTML='';return;}
let minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;for(const[x,y]of coords){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);}const cos=Math.cos((minY+maxY)/2*Math.PI/180),scale=Math.min(740/((maxX-minX)*cos),450/(maxY-minY));const width=(maxX-minX)*cos*scale,height=(maxY-minY)*scale;const project=([x,y])=>[(800-width)/2+(x-minX)*cos*scale,(500-height)/2+(maxY-y)*scale];
const path=g=>(g.type==='Polygon'?[g.coordinates]:g.coordinates).map(poly=>poly.map(ring=>ring.map((p,i)=>`${i?'L':'M'}${project(p).map(n=>n.toFixed(2)).join(',')}`).join('')+'Z').join('')).join('');
const margin=f=>{const base=featureBenchmark(f),p=f.properties;if(state.layer==='historical')return ElectionBenchmarks.usable(base)?100*(base.democratic_votes-base.republican_votes)/(base.democratic_votes+base.republican_votes):null;if(state.layer==='boundaries')return null;const observed=p.kind==='county'?(r.county_results||[]).find(c=>c.county_id===p.county_id):mappedUnit(f,r);const votes=twoParty(observed||{});if(state.layer==='target'){if(!comparableRace())return null;const target=targetFor(base);return votes.total&&target!=null?100*votes.d/votes.total-target:null;}return ballotMargin(observed);};
const shapes=mapFeatures.map((f,i)=>`<path class="area" data-area="${i}" data-kind="${f.properties.kind}" data-feature-id="${esc(f.properties.id)}" d="${path(f.geometry)}" fill="${mapColor(margin(f))}" fill-rule="evenodd" tabindex="0" role="button" aria-label="${esc(f.properties.name)}; ${f.properties.kind==='county'?(statewideCountyView()?'county':'county portion'):'precinct portion'}"/>`).join('');

$('map-shapes').innerHTML=(district?`<defs><clipPath id="seat-clip" clipPathUnits="userSpaceOnUse"><path d="${path(district.geometry)}"/></clipPath></defs><g clip-path="url(#seat-clip)">${shapes}</g><path class="district-outline" d="${path(district.geometry)}"/>`:shapes);
$('legend').innerHTML=state.layer==='live'&&referendum()?'<span><span class="swatch yes"></span>Yes +30 pp or more</span><span>Even</span><span><span class="swatch no"></span>No +30 pp or more</span><span><span class="swatch"></span>No usable current votes</span>':state.layer==='boundaries'?`<span><span class="swatch"></span>${statewideCountyView()?'County boundary':'Seat-clipped reporting area'}</span>`:`<span><span class="swatch dem"></span>${state.layer==='target'?(state.targetParty==='dem'?'Above target':'Below target'):'D +30 pp or more'}</span><span>Even</span><span><span class="swatch rep"></span>${state.layer==='target'?(state.targetParty==='dem'?'Below target':'Above target'):'R +30 pp or more'}</span><span><span class="swatch"></span>${state.layer==='historical'?'No usable benchmark':'No usable current votes'}</span>`;
$('map-note').textContent=(scope==='alabama'?'Alabama’s 67 whole counties. Hover or select a county for details. ':seat?(scope==='cd2'?'County areas are clipped to the current AL-02 district. ':'Areas are clipped to the selected seat: Madison precincts and county portions elsewhere. '):'Madison County reporting areas. ')+(state.layer==='historical'?(scope==='alabama'?'2024 presidential whole-county reference results.':'2024 presidential benchmarks are Census-weighted estimates on these areas, including source-allocated central ballots.'):state.layer==='target'?'Current two-party shares compared with the selected target for the same modeled area. This is a provisional comparison, not a forecast.':'Live votes retain their published precinct or county level; no votes are allocated by map area.')+(seat?' Tiny county boundary artifacts are excluded.':'')+(!state.data.current_map_compatible?' Current Madison map identity is unverified; its geographic vote joins are disabled.':'');
$('map-shapes').querySelectorAll('[data-area]').forEach(el=>{const f=mapFeatures[Number(el.dataset.area)];const preview=()=>{$('map-preview').innerHTML=featureText(f)};el.onpointerenter=preview;el.onfocus=preview;el.onpointerleave=()=>{$('map-preview').textContent='Move over an area to inspect it. Select an area to keep its details open.'};el.onblur=el.onpointerleave;const select=()=>{state.selected=mappedUnit(f,r)?.id||f.properties.id;renderSelection();renderTable();highlightSelection()};el.onclick=()=>{if(!dragged)select()};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}}});
let drag=null,dragged=false;const svg=$('map');svg.onpointerdown=e=>{dragged=false;if(state.zoom>1)drag={x:e.clientX,y:e.clientY,px:state.panX,py:state.panY}};svg.onpointermove=e=>{if(drag){const dx=(e.clientX-drag.x)*800/svg.clientWidth,dy=(e.clientY-drag.y)*500/svg.clientHeight;if(Math.abs(dx)+Math.abs(dy)>5)dragged=true;state.panX=drag.px+dx;state.panY=drag.py+dy;transformMap()}};svg.onpointerup=()=>{drag=null};svg.onpointerleave=()=>{drag=null};transformMap();highlightSelection();}
function transformMap(){$('map-shapes')?.setAttribute('transform',`translate(${400+state.panX} ${250+state.panY}) scale(${state.zoom}) translate(-400 -250)`)}
function referenceText(base){if(!ElectionBenchmarks.usable(base))return '2024 benchmark unavailable for this area.';return `2024 presidential reference: ${pct(referenceShare(base))} ${state.targetParty==='dem'?'D':'R'}; target ${pct(selectedTarget(base))}; ≈ ${fmt(Math.round(base.two_party_votes))} historical two-party votes. ${statewideCountyView()?'Whole-county source totals; original source allocation caveat retained.':base.is_estimate?'Historical geography is modeled.':'Whole-county historical reference.'}`}
function featureText(f){const p=f.properties,base=featureBenchmark(f);const observed=p.kind==='county'?(race().county_results||[]).find(c=>c.county_id===p.county_id):mappedUnit(f,race());const result=comparison(base,observed);return `<strong>${esc(p.name)}${p.kind==='county'?(statewideCountyView()?' County':' County portion'):''}</strong>${observed?fmt(observed.total)+' current published candidate votes. ':'No accepted current return matched to this area. '}${esc(referenceText(base))} ${esc(turnoutDetail(base,observed))}${result.gap!=null?' Current gap '+signed(result.gap)+'.':''}`}
function highlightSelection(){$('map-shapes')?.querySelectorAll('[data-area]').forEach(el=>{const f=mapFeatures[Number(el.dataset.area)];const u=mappedUnit(f,race());el.classList.toggle('selected',f.properties.id===state.selected||u?.id===state.selected)})}
function renderSelection(){const out=$('selection');if(!out)return;if(!state.selected){out.innerHTML='';return}const u=race().units.find(u=>u.id===state.selected);const f=mapFeatures.find(f=>f.properties.id===state.selected||mappedUnit(f,race())?.id===state.selected);const observed=u||(f?.properties.kind==='county'?(race().county_results||[]).find(c=>c.county_id===f.properties.county_id):null);const base=u?historicalFor(u):f?featureBenchmark(f):null;out.innerHTML=`<div class="selected-detail"><button id="clear-selection" class="button">Clear</button><h3>${esc(u?.name||f?.properties.name||'Selected area')}</h3>${observed?(observed.candidates||[]).map(c=>`<p class="${party(c.party)}">${esc(c.name)}: <strong>${fmt(c.votes)}</strong></p>`).join(''):'<p>No current return matched to this area.</p>'}<p class="note">${esc(referenceText(base))}</p>${turnoutDetail(base,observed)?`<p>${esc(turnoutDetail(base,observed))}</p>`:''}${comparison(base,observed).gap!=null?`<p>Current target gap: <strong>${signed(comparison(base,observed).gap)}</strong></p>`:''}</div>`;$('clear-selection').onclick=()=>{state.selected=null;renderSelection();renderTable();highlightSelection()}}
function renderHistory(){const r=race();const relevant=(h,c)=>(c.provider_id?r.contributions.some(x=>x.source_id===h.source_id&&x.provider_id===c.provider_id&&(!c.county||x.county===c.county)):c.race===r.provider_name||c.race===r.name);const entries=state.data.history.filter(h=>(h.changes||[]).some(c=>relevant(h,c))).slice(0,20);$('history').innerHTML=entries.length?entries.map(h=>`<div class="history-entry"><time>${esc(time(h.at))}</time><div><strong>${esc(h.source_id)} · revision ${esc(h.version)}</strong>${(h.changes||[]).filter(c=>relevant(h,c)).map(c=>`<p>${esc(c.race)}${c.county?' ('+esc(c.county)+')':''}: ${fmt(c.before)} → ${fmt(c.after)} votes ${c.correction?'(source correction)':''}</p>`).join('')}</div></div>`).join(''):'<p class="empty">Accepted source updates and vote corrections will appear here. Refreshing the view does not create a results update.</p>'}
function exportRace(){const r=race();const fields=['election','race','county','reporting_unit_id','unit','administrative','candidate','party','votes','reporting_complete','reporting_basis','presidential_votes_2024','turnout_pct_of_2024','turnout_lower_bound','historical_estimate'];const rows=[fields,...r.units.flatMap(u=>u.candidates.map(c=>[state.data.election,r.name,u.county,u.id,u.name,u.administrative,c.name,c.party,c.votes,u.reporting_complete,u.reporting_basis,historicalFor(u)?.total_votes,turnoutFor(historicalFor(u),u)?.percent,turnoutFor(historicalFor(u),u)?.lowerBound,historicalFor(u)?.is_estimate]))];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`alabama-2026-${r.id}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCounties(){const r=race();const rows=[['election','race','county','county_fips','reporting_level','publisher','source_id','candidate','source_candidate_name','party','votes','write_ins_supplied','published_at','retrieved_at','reporting_complete','reporting_basis','presidential_votes_2024','turnout_pct_of_2024','turnout_lower_bound','historical_estimate'],...(r.county_results||[]).flatMap(c=>(c.candidates||[]).map(x=>[state.data.election,r.name,c.county,c.county_id,c.granularity,c.publisher,c.source_id,x.name,x.source_name||x.name,x.party,x.votes,c.write_ins_supplied,c.published_at,c.fetched_at,c.reporting_complete,c.reporting_basis,benchmarkForCounty(c)?.total_votes,turnoutFor(benchmarkForCounty(c),c)?.percent,turnoutFor(benchmarkForCounty(c),c)?.lowerBound,benchmarkForCounty(c)?.is_estimate]))];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`alabama-2026-${r.id}-counties.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportBenchmarks(){const rows=[['scope','feature_id','area','level','available','method','estimated','democratic_2024','republican_2024','other_2024','two_party_2024','adult_mass','selected_party','selected_overall_target','area_target'],...benchmarkRecords().map(u=>[benchmarkScope(),u.id,u.name,u.kind,u.available,u.method,u.is_estimate,u.democratic_votes,u.republican_votes,u.other_votes,u.two_party_votes,u.adult_mass,state.targetParty,state.target,selectedTarget(u)])];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`alabama-2024-${benchmarkScope()}-benchmarks.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function renderSources(){const audit=state.data.coverage_research?.counties||[];$('main').innerHTML=`<h1>Sources &amp; coverage</h1><p class="scope">Live collection accepts verified November 3 general-election data. Historical files and publisher-labeled tests remain separate.</p><div class="notice">Madison’s November 3 general-election feed is configured and validated. Its setup snapshot contains zero votes. Morgan’s precinct report remains quarantined while its authority labels it <strong>TEST RESULTS</strong>. Statewide county feeds for Senate, Governor, executive offices and statewide amendments, plus all six CD-5 counties and Limestone’s SD-2 and HD-25 returns, update automatically through <a href="https://civicapi.org/" target="_blank" rel="noreferrer">civicAPI</a>. AL-02 also has an automatic, district-specific feed for all 16 counties; its view lists the official precinct-source checks. County totals are kept separate from precinct detail. PSC and statewide judicial races currently have accepted Madison results only; their statewide views show the remaining counties as unavailable.</div><div class="sources">${state.data.sources.map(s=>{const c=audit.find(c=>c.county===s.source.county);return `<section class="source"><h2>${esc(s.source.county)}${s.source.county_id==='AL'?'':' County'}</h2><p>${esc(sourceStatus(s))}</p><p>${esc(s.source.note)}</p><dl><dt>${s.source.format==='civic_county'?'Publisher feed':'Official entry point'}</dt><dd><a href="${esc(s.source.url)}" target="_blank" rel="noreferrer">${esc(s.source.url)}</a></dd><dt>Provider publication time</dt><dd>${esc(time(s.published_at))}</dd><dt>Latest accepted retrieval</dt><dd>${esc(time(s.fetched_at))}${s.stale?' · stale':''}</dd><dt>Last collection attempt</dt><dd>${esc(time(s.attempted_at))}</dd>${s.relay?`<dt>Delivery</dt><dd>Local computer → GitHub; original retrieval time above. Last imported ${esc(time(s.relay.received_at))}. Precinct updates require the local computer to remain awake and online; county feeds continue in GitHub.</dd>`:''}<dt>Collection</dt><dd>${s.source.enabled?(s.source.format==='civic_county'?'civicAPI county totals, central polling every 120 seconds':s.source.id==='morgan'?'Authority-label preflight every 10 minutes; test results rejected':'Official-page discovery every 10 minutes; verified configured feeds at least 120 seconds apart'):'Official source not polled; automatic county fallback feeds are listed separately'}</dd></dl>${s.error?`<div class="notice">Last attempt: ${esc(s.error)}</div>`:''}${c?`<details><summary>Research notes</summary><p>${esc(Array.isArray(c.notes)?c.notes.join(' '):c.notes||c.readiness)}</p>${c.endpoint?`<p>Candidate feed: <a href="${esc(c.endpoint)}" target="_blank" rel="noreferrer">${esc(c.endpoint)}</a>. ${c.test?'Publisher-labeled test; quarantined.':''}</p>`:''}</details>`:''}</section>`}).join('')}</div><section class="section prose"><h2>Coverage rules</h2><p>The district spans Jackson, Lawrence, Limestone, Madison, Morgan and eastern Lauderdale. Only accepted district-specific returns enter CD-5 totals. Countywide results for another office never stand in for the congressional race.</p><p>All 49 Madison sample-ballot contests are listed, including uncontested races and five ballot measures. The sample ballot covers offices that apply to different parts of the county. It does not mean every voter receives every contest.</p><p><a href="https://www.sos.alabama.gov/sites/default/files/sample-ballots/2026/gen/Madison-Sample.pdf" target="_blank" rel="noreferrer">Official Madison County sample ballot</a> · <a href="https://www.limestonecounty-al.gov/Departments/Elections" target="_blank" rel="noreferrer">Limestone live video page</a></p></section>`}
function renderMethodology(){$('main').innerHTML=`<article class="prose"><h1>Reading the returns</h1><p>The desk covers AL-02, Alabama county views for statewide races, all 49 Madison ballot contests and seat views for CD-5, HD-10, HD-20, HD-21, HD-25, SD-2 and SD-7. Candidate totals and maps retain their source reporting level.</p><h2>AL-02</h2><p>The AL-02 view follows the current 2026 plan and its 16-county roster, including partial Covington and Elmore. The 2024 presidential reference is modeled onto this current seat, not copied from the 2024 AL-02 race. County contributions are contest-specific and counted once; source checks are listed in the view. Precinct data is accepted only after verifying the current general election and reconciling candidate counts. County totals are never distributed over precincts.</p><h2>Statewide county views</h2><p>Senate, Governor, executive offices and statewide amendments use verified civicAPI county feeds across Alabama. The statewide view shows 67 full counties with 2024 presidential county references. Use Coverage to switch to Madison precinct detail. PSC and statewide judicial county feeds have not been verified; their views retain the accepted Madison contribution and explicitly mark the missing statewide coverage. A partial sum is not a complete statewide result.</p><h2>Automatic county fallback</h2><p>Madison’s official Clarity feed supplies precinct detail. Where verified precinct data is unavailable, civicAPI supplies candidate-level county totals. Limestone’s CD-5, HD-25 and SD-2 returns therefore update automatically. civicAPI is a public results publisher, not a direct county authority connection. It currently omits write-ins, and its reporting percentage is estimated.</p><p>Only one source contributes for each race and county. A healthy precinct source is preferred; a healthy county source can replace a failed or stale precinct source. Overlapping county and precinct totals are never added. Raw snapshots and source-specific timestamps remain separate.</p><h2>Seat-clipped maps</h2><p>Each of the seven seat maps clips Madison’s current provider precincts to the reference seat boundary. Outside Madison it shows county portions clipped to that same seat. The county-only map option is clipped too. Tiny county intersections caused by differing map resolution are excluded. Polygon clipping does not allocate live votes; the selected contest’s published precinct and county totals remain intact.</p><p>District references use Census 2026 CD120, Census 2025 House districts and the 2025 remedial Senate plan. Map simplification and source precision produce small gaps and overlaps. Historical calculations use the original unsimplified district inputs; display and original membership differ for two Census adults in HD-20.</p><h2>2024 presidential benchmarks</h2><p>Statewide references copy the source’s integer 2024 whole-county totals without a new spatial allocation. The original source’s central-ballot allocation qualification remains attached.</p><p>Every available benchmark uses Harris and Trump’s 2024 results. For seat and Madison precinct benchmarks, original 2024 precinct counts are assigned to current reporting areas and seat portions using 2020 Census adult-population block internal points. Each party receives the same geographic allocation weight. Outside Madison the resulting estimates are combined into the county portion of the seat. No land-area allocation or live-vote allocation is used.</p><p>All benchmarks are labeled estimates: the historical source already distributes centrally reported ballots to precincts, Census points are not household locations, and population and turnout changed after 2020. Areas with no usable adult weight receive a dash rather than invented votes. The modeled available reference accounts for all positive adult mass in the seven reference seats; this does not certify exact 2024 split-precinct results.</p><p>Other Madison ballot races use the countywide current-precinct reference. Administrative absentee and provisional rows have no geographic benchmark. The current provider map ID and source hash must still match before precinct returns are compared with modeled areas.</p><h2>Targets and reported comparisons</h2><p>A uniform shift of local 2024 Democratic shares is calibrated, with 0–100% limits, so the historical two-party-weighted share across the selected seat’s available areas equals your chosen target. Republican targets use the Democratic complement. This produces a local target for each precinct and county portion.</p><p>The provisional gap compares actual and target shares for the same reported two-party vote mix. Matched positive precinct rows and county-only contributions enter once; administrative precinct rows are excluded. County-only observations are compared to county-part benchmarks and are never distributed over precincts. A D/R gap is withheld where the candidate field does not contain both parties.</p><p>Turnout vs 2024 compares current reported contest votes with total 2024 presidential votes (all choices). It appears only when the source reports 100% progress or explicitly marks a precinct complete. County publisher progress can be estimated; these indicators do not certify that all ballots are final. A ≥ symbol qualifies sources that omit write-ins, and ≈ marks estimated historical geography. Administrative units and missing or zero historical totals are unavailable. This is vote volume relative to 2024, not registered-voter turnout or ballots cast.</p><p>This is a historical reference comparison, not an estimate of remaining votes, a projected finish, a probability or a race call. Candidate percentages use published candidate totals, with missing county write-ins explicitly qualified.</p><h2>Updates and corrections</h2><p>The central collector validates election date, identity and test status. Browser refreshes read its cache every 30 seconds; source polling is at least 120 seconds apart within the running process. Provider publication, observation retrieval and view-refresh times have separate labels. Failures retain accepted cached values with a source issue, and accepted downward vote corrections are recorded.</p><p>County totals: <a href="https://civicapi.org/" target="_blank" rel="noreferrer">civicAPI</a>. <a href="https://www.sos.alabama.gov/sites/default/files/sample-ballots/2026/gen/Madison-Sample.pdf" target="_blank" rel="noreferrer">Official sample ballot</a>. <a href="https://www.sos.alabama.gov/alabama-votes/voter/election-data" target="_blank" rel="noreferrer">Alabama historical results</a>.</p></article>`}
async function refresh(initial=false){$('refresh').disabled=true;try{if(initial){const results=await Promise.all(['/api/state','/data/geography.json','/data/baseline.json','/data/current-geography.json','/data/seat-geography.json','/data/seat-benchmarks.json','/data/statewide-geography.json','/data/statewide-benchmarks.json','/data/al02-geography.json','/data/al02-benchmarks.json'].map(async url=>{const r=await fetch(dataURL(url),{cache:'no-store'});if(!r.ok)throw Error(`${url}: HTTP ${r.status}`);return r.json()}));[state.data,state.geo,state.baseline,state.currentGeo,state.seatGeo,state.seatBench,state.statewideGeo,state.statewideBench,state.al02Geo,state.al02Bench]=results;ageSources();route()}else{const r=await fetch(dataURL('/api/state'),{cache:'no-store'});if(!r.ok)throw Error('Cached results unavailable (HTTP '+r.status+')');state.data=await r.json();ageSources();const active=document.activeElement;const typing=active&&['INPUT','SELECT'].includes(active.tagName);if(!typing)render();else renderStatus()}$('error').hidden=true}catch(e){$('error').hidden=false;$('error').textContent='Could not refresh the cached dashboard. '+e.message+(state.data?' Last loaded data remains visible.':' Check that the local server is running.')}finally{$('refresh').disabled=false}}
$('race-search').oninput=e=>{state.search=e.target.value;if(state.data)renderRail()};$('race-group').onchange=e=>{state.group=e.target.value;if(state.data)renderRail()};$('refresh').onclick=()=>refresh();window.addEventListener('hashchange',route);document.addEventListener('keydown',e=>{if(e.key==='Escape'){state.selected=null;renderSelection();highlightSelection()}});refresh(true);setInterval(()=>refresh(),30000);
